-- Applied as kus_music_unified_platform_foundation on 2026-11-13.
-- Store KUS identities and authorized provider references, never copied third-party audio.
create table if not exists public.music_catalog_tracks(id uuid primary key default gen_random_uuid(),canonical_key text not null unique,title text not null,primary_artist text not null,album_title text,release_date date,duration_ms integer check(duration_ms is null or duration_ms>=0),genre text,mood_tags text[] not null default '{}',artwork_url text,metadata jsonb not null default '{}'::jsonb,metadata_policy text not null default 'provider_restricted' check(metadata_policy in('provider_allowed','ephemeral_only','provider_restricted','user_supplied')),status text not null default 'active' check(status in('active','partially_unavailable','unavailable')),last_seen_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists music_catalog_tracks_search_idx on public.music_catalog_tracks using gin(to_tsvector('simple',coalesce(title,'')||' '||coalesce(primary_artist,'')||' '||coalesce(album_title,'')));
create index if not exists music_catalog_tracks_artist_idx on public.music_catalog_tracks(lower(primary_artist));
alter table public.music_catalog_tracks enable row level security;
drop policy if exists "Music catalogue is publicly readable" on public.music_catalog_tracks;
create policy "Music catalogue is publicly readable" on public.music_catalog_tracks for select to anon,authenticated using(true);
revoke insert,update,delete on public.music_catalog_tracks from anon,authenticated;grant select on public.music_catalog_tracks to anon,authenticated;grant all on public.music_catalog_tracks to service_role;
create table if not exists public.music_catalog_sources(id uuid primary key default gen_random_uuid(),catalog_track_id uuid not null references public.music_catalog_tracks(id) on delete cascade,provider text not null check(provider in('youtube','spotify','apple_music','soundcloud','jamendo','openverse','native')),provider_track_id text not null,provider_uri text,source_url text not null,embed_url text,playback_mode text not null check(playback_mode in('official_embed','official_sdk','native_upload','link_only')),availability text not null default 'unknown' check(availability in('available','unavailable','region_restricted','unknown')),attribution text,metadata_policy text not null default 'provider_restricted' check(metadata_policy in('provider_allowed','ephemeral_only','provider_restricted','user_supplied')),provider_metadata jsonb not null default '{}'::jsonb,last_checked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,provider_track_id));
create index if not exists music_catalog_sources_track_idx on public.music_catalog_sources(catalog_track_id);create index if not exists music_catalog_sources_provider_idx on public.music_catalog_sources(provider,availability);
alter table public.music_catalog_sources enable row level security;drop policy if exists "Music provider references are publicly readable" on public.music_catalog_sources;create policy "Music provider references are publicly readable" on public.music_catalog_sources for select to anon,authenticated using(true);revoke insert,update,delete on public.music_catalog_sources from anon,authenticated;grant select on public.music_catalog_sources to anon,authenticated;grant all on public.music_catalog_sources to service_role;
create table if not exists public.music_studio_projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Untitled project' check(length(trim(title)) between 1 and 100),tempo integer not null default 110 check(tempo between 40 and 240),time_signature text not null default '4/4',project_data jsonb not null default '{"version":1,"tracks":[],"patterns":[],"clips":[]}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists music_studio_projects_owner_updated_idx on public.music_studio_projects(user_id,updated_at desc);alter table public.music_studio_projects enable row level security;
drop policy if exists "Users read own studio projects" on public.music_studio_projects;create policy "Users read own studio projects" on public.music_studio_projects for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users create own studio projects" on public.music_studio_projects;create policy "Users create own studio projects" on public.music_studio_projects for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists "Users update own studio projects" on public.music_studio_projects;create policy "Users update own studio projects" on public.music_studio_projects for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users delete own studio projects" on public.music_studio_projects;create policy "Users delete own studio projects" on public.music_studio_projects for delete to authenticated using((select auth.uid())=user_id);grant select,insert,update,delete on public.music_studio_projects to authenticated;
create table if not exists public.music_trend_follows(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,target_type text not null check(target_type in('genre','artist','country','mood')),target_value text not null check(length(trim(target_value)) between 1 and 100),created_at timestamptz not null default now());
create unique index if not exists music_trend_follows_unique_idx on public.music_trend_follows(user_id,target_type,lower(target_value));alter table public.music_trend_follows enable row level security;
drop policy if exists "Users manage own music trend follows" on public.music_trend_follows;create policy "Users manage own music trend follows" on public.music_trend_follows for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);grant select,insert,update,delete on public.music_trend_follows to authenticated;
create table if not exists public.music_trend_signals(id uuid primary key default gen_random_uuid(),signal_key text not null unique,signal_type text not null check(signal_type in('search','verified_listen','repeat_listen','like','save','playlist_add','artist_growth','new_release','provider_chart')),region text,genre text,artist_name text,provider text,source_ref text,score numeric not null default 0,confidence numeric not null default 0 check(confidence between 0 and 1),suspicious boolean not null default false,observed_at timestamptz not null default now(),expires_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create index if not exists music_trend_signals_recent_idx on public.music_trend_signals(observed_at desc) where suspicious=false;alter table public.music_trend_signals enable row level security;revoke all on public.music_trend_signals from anon,authenticated;grant all on public.music_trend_signals to service_role;
create table if not exists public.music_auto_playlists(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,description text not null default '',rule jsonb not null default '{}'::jsonb,region text,genre text,mood text,refresh_interval_minutes integer not null default 360 check(refresh_interval_minutes between 30 and 10080),last_refreshed_at timestamptz,next_refresh_at timestamptz,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.music_auto_playlists enable row level security;drop policy if exists "Active music auto playlists are readable" on public.music_auto_playlists;create policy "Active music auto playlists are readable" on public.music_auto_playlists for select to anon,authenticated using(active=true);grant select on public.music_auto_playlists to anon,authenticated;grant all on public.music_auto_playlists to service_role;
create table if not exists public.music_auto_playlist_tracks(id uuid primary key default gen_random_uuid(),playlist_id uuid not null references public.music_auto_playlists(id) on delete cascade,catalog_track_id uuid not null references public.music_catalog_tracks(id) on delete cascade,position integer not null check(position>=0),reason text not null default '',score numeric not null default 0,added_at timestamptz not null default now(),unique(playlist_id,catalog_track_id),unique(playlist_id,position));
alter table public.music_auto_playlist_tracks enable row level security;drop policy if exists "Active auto playlist tracks are readable" on public.music_auto_playlist_tracks;create policy "Active auto playlist tracks are readable" on public.music_auto_playlist_tracks for select to anon,authenticated using(exists(select 1 from public.music_auto_playlists p where p.id=playlist_id and p.active=true));grant select on public.music_auto_playlist_tracks to anon,authenticated;grant all on public.music_auto_playlist_tracks to service_role;
alter table public.music_playlists add column if not exists visibility text not null default 'private' check(visibility in('private','public','unlisted'));alter table public.music_playlists add column if not exists is_collaborative boolean not null default false;alter table public.music_playlists add column if not exists artwork_url text;alter table public.music_playlists add column if not exists last_played_at timestamptz;
create table if not exists public.music_playlist_collaborators(playlist_id uuid not null references public.music_playlists(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,invited_by uuid not null references auth.users(id) on delete cascade,role text not null default 'editor' check(role in('editor','viewer')),status text not null default 'pending' check(status in('pending','accepted')),created_at timestamptz not null default now(),primary key(playlist_id,user_id));
alter table public.music_playlist_collaborators enable row level security;drop policy if exists "Users view relevant playlist collaboration" on public.music_playlist_collaborators;create policy "Users view relevant playlist collaboration" on public.music_playlist_collaborators for select to authenticated using(user_id=(select auth.uid()) or invited_by=(select auth.uid()));
drop policy if exists "Playlist owners invite collaborators" on public.music_playlist_collaborators;create policy "Playlist owners invite collaborators" on public.music_playlist_collaborators for insert to authenticated with check(invited_by=(select auth.uid()) and exists(select 1 from public.music_playlists p where p.id=playlist_id and p.user_id=(select auth.uid())));
drop policy if exists "Playlist owners remove collaborators" on public.music_playlist_collaborators;create policy "Playlist owners remove collaborators" on public.music_playlist_collaborators for delete to authenticated using(exists(select 1 from public.music_playlists p where p.id=playlist_id and p.user_id=(select auth.uid())));grant select,insert,delete on public.music_playlist_collaborators to authenticated;
create table if not exists public.music_playlist_saves(playlist_id uuid not null references public.music_playlists(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(playlist_id,user_id));
alter table public.music_playlist_saves enable row level security;drop policy if exists "Users manage own playlist saves" on public.music_playlist_saves;create policy "Users manage own playlist saves" on public.music_playlist_saves for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);grant select,insert,delete on public.music_playlist_saves to authenticated;
drop policy if exists "Users read public or collaborated playlists" on public.music_playlists;create policy "Users read public or collaborated playlists" on public.music_playlists for select to anon,authenticated using(visibility in('public','unlisted') or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=id and c.user_id=(select auth.uid()) and c.status='accepted'));
drop policy if exists "Users read public or collaborated playlist tracks" on public.music_playlist_tracks;create policy "Users read public or collaborated playlist tracks" on public.music_playlist_tracks for select to anon,authenticated using(exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.visibility in('public','unlisted') or p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted'))));
drop policy if exists "Collaborators edit shared playlist tracks" on public.music_playlist_tracks;create policy "Collaborators edit shared playlist tracks" on public.music_playlist_tracks for all to authenticated using(exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted' and c.role='editor')))) with check(exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted' and c.role='editor'))));
